#include <bits/stdc++.h>
using namespace std;

struct CharInfo {
    char chr;
    int val;
    int idx;
    CharInfo(char c, int v, int i) : chr(c), val(v), idx(i) {}
};

void swapChars(vector<char>& chArr, vector<int>& vals, int i) {
    char tempChar = chArr[i];
    chArr[i] = chArr[chArr.size() - i - 1];
    chArr[chArr.size() - i - 1] = tempChar;

    int tempVal = vals[i];
    vals[i] = vals[vals.size() - i - 1];
    vals[vals.size() - i - 1] = tempVal;
}

bool isAntiPalindrome(const vector<char>& chArr) {
    int len = chArr.size();
    for (int i = 0; i < len / 2; i++) {
        if (chArr[i] == chArr[len - i - 1]) {
            return false;
        }
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int length;
    cin >> length;
    cin.ignore();
    string inputLine;
    getline(cin, inputLine);
    inputLine.erase(remove_if(inputLine.begin(), inputLine.end(), ::isspace), inputLine.end());
    vector<char> arrayChars(inputLine.begin(), inputLine.end());

    vector<int> arrayVals(length);
    for (int i = 0; i < length; i++) {
        cin >> arrayVals[i];
    }
    cin.ignore();

    vector<CharInfo> mismatchList;
    vector<CharInfo> pairList;

    for (int i = 0; i < length / 2; i++) {
        if (arrayVals[i] > arrayVals[length - i - 1]) {
            swapChars(arrayChars, arrayVals, i);
        }
        CharInfo ci(arrayChars[i], arrayVals[i], i);
        if (arrayChars[i] == arrayChars[length - i - 1]) {
            mismatchList.push_back(ci);
        }
        pairList.push_back(ci);
    }

    std::sort(pairList.begin(), pairList.end(), [](const CharInfo& a, const CharInfo& b) {
        return a.val < b.val;
    });

    int totalDifference = 0;
    if (!isAntiPalindrome(arrayChars)) {
        if (mismatchList.size() == 1) {
            CharInfo wrongChar = mismatchList[0];
            for (const auto& ci : pairList) {
                if (ci.chr != wrongChar.chr && arrayChars[length - ci.idx - 1] != wrongChar.chr) {
                    totalDifference = wrongChar.val + ci.val;
                    break;
                }
            }
        } else if (mismatchList.size() > 1) {
            std::unordered_map<char, int> countMap;
            for (const auto& ci : mismatchList) {
                countMap[ci.chr]++;
            }
            int maxCount = 0;
            for (const auto& kv : countMap) {
                if (kv.second > maxCount) maxCount = kv.second;
            }
            vector<CharInfo> appendList;
            while (maxCount * 2 > mismatchList.size() + (int)appendList.size()) {
                auto maxEntry = std::max_element(countMap.begin(), countMap.end(),
                    [](const pair<char,int>& a, const pair<char,int>& b) {
                        return a.second < b.second;
                    });
                char maxChar = maxEntry->first;
                for (const auto& ci : pairList) {
                    if (ci.chr != maxChar && arrayChars[length - ci.idx - 1] != maxChar && 
                        find_if(mismatchList.begin(), mismatchList.end(), [&](const CharInfo& c){ return c.chr == ci.chr; }) == mismatchList.end() &&
                        find_if(appendList.begin(), appendList.end(), [&](const CharInfo& c){ return c.chr == ci.chr; }) == appendList.end()) {
                        appendList.push_back(ci);
                        break;
                    }
                }
                // Recompute maxCount
                countMap[maxChar]++;
                maxCount = 0;
                for (const auto& kv : countMap) {
                    if (kv.second > maxCount) maxCount = kv.second;
                }
            }
            int sumMismatch = 0;
            for (const auto& c : mismatchList) sumMismatch += c.val;
            int sumAppend = 0;
            for (const auto& c : appendList) sumAppend += c.val;
            totalDifference = sumMismatch + sumAppend;
        }
    }

    int sumAll = 0;
    for (int v : arrayVals) sumAll += v;
    cout << sumAll - totalDifference << "\n";

    return 0;
}
